// This Code Node processes the Apify dataset, groups posts by page, finds the last post date, and filters pages that haven't posted in over X days (e.g., 30 days).

const DORMANT_DAYS = 30; // <<< Set your dormancy period here (in days)
const CUTOFF_DATE = new Date();
CUTOFF_DATE.setDate(CUTOFF_DATE.getDate() - DORMANT_DAYS);

// Assuming the Apify output is an array of posts/pages
const allPosts = $input.all().map(i => i.json);

// 1. Group posts by page ID (or URL) and extract post style
const pages = allPosts.reduce((acc, post) => {
  // Find a reliable identifier for the page
  const pageIdentifier = post.pageUrl || post.url || post.pageId || post.title || post.name || 'UNKNOWN';

  if (!acc[pageIdentifier]) {
    acc[pageIdentifier] = {
      pageUrl: post.pageUrl || post.url || pageIdentifier,
      pageName: post.pageName || post.title || post.name || pageIdentifier,
      posts: [],
      sourceKeyword: post.sourceKeyword || $json.keyword // Inherit keyword
    };
  }

  // Extract post date and content
  const postDate = post.createdAt || post.datePublished || post.publishDate;

  if (postDate) {
    acc[pageIdentifier].posts.push({
      date: new Date(postDate),
      content: post.text || post.description || post.content || '',
    });
  }
  return acc;
}, {});

const dormantPages = [];

// 2. Determine last post and filter dormant pages
for (const id in pages) {
  const page = pages[id];

  // Handle pages with no scraped posts (treat as dormant)
  if (page.posts.length === 0) {
      page.lastPostDate = 'Never posted (or no date found)';
      page.postStyles = 'No recent posts found to analyze.';
      dormantPages.push(page);
      continue;
  }

  // Find the latest post date
  const latestPost = page.posts.reduce((max, post) => (
    (post.date > max.date) ? post : max
  ), { date: new Date(0) });

  page.lastPostDate = latestPost.date.toISOString().split('T')[0];

  // Extract post styles from the most recent 3 posts
  page.postStyles = page.posts
      .sort((a, b) => b.date - a.date)
      .slice(0, 3)
      .map(p => p.content.substring(0, 500) + '...')
      .join('\n--- POST BREAK ---\n');

  // Check for dormancy
  if (latestPost.date < CUTOFF_DATE) {
    dormantPages.push(page);
  }
}

// 3. Output the dormant pages for the next node (AI)
return dormantPages.map(page => ({
    json: {
        pageName: page.pageName,
        pageUrl: page.pageUrl,
        lastPostDate: page.lastPostDate,
        postStyles: page.postStyles,
        sourceKeyword: page.sourceKeyword
    }
}));

// This Code Node parses the raw AI response (which should be a JSON string) and combines it with the original page data.

const originalData = $input.item.json;
// Assuming the AI agent output is in originalData.result
const aiResponse = originalData.result || originalData.text || ''; 

// 1. Extract the JSON from the AI's response string (often starts/ends with ```json)
let jsonString = aiResponse.trim();
if (jsonString.startsWith('```json')) {
  jsonString = jsonString.substring(7, jsonString.lastIndexOf('```')).trim();
}

let parsedDMs;
try {
  parsedDMs = JSON.parse(jsonString);
} catch (e) {
  // Log error but proceed to prevent workflow failure
  console.error('AI JSON Parse Error:', e);
  parsedDMs = {};
}

// 2. Structure the final data for Google Sheets
return [
  {
    json: {
      'Source Keyword': originalData.sourceKeyword || 'N/A',
      'Facebook Page Name': originalData.pageName || 'N/A',
      'Page URL': originalData.pageUrl || 'N/A',
      'Last Post Date': originalData.lastPostDate || 'N/A',
      'DM 1 - Outreach': parsedDMs.DM_1_Outreach || 'Error/N/A',
      'DM 2 - Outreach': parsedDMs.DM_2_Followup || parsedDMs.DM_2_Outreach || 'Error/N/A',
      'DM 3 - Outreach': parsedDMs.DM_3_FinalAttempt || parsedDMs.DM_3_Outreach || 'Error/N/A'
    }
  }
];

